// A matrix class using expression templates (a proxy pattern)
template<typename T> class Matrix { /* ... */ };

// Proxy class representing the sum of two matrices
template<typename T1, typename T2>
class SumProxy { /* ... */ };

// operator+ returns a proxy, not a Matrix
SumProxy<Matrix<int>, Matrix<int>>
operator+(const Matrix<int>&, const Matrix<int>&);

Matrix<int> m1, m2, m3, m4;

// Deduces the proxy type, which might be dangerous if m1 or m2 change
auto proxy = m1 + m2; // type is SumProxy<Matrix<int>, Matrix<int>>

// Correct approach: Force the conversion to the desired value type
auto sum = static_cast<Matrix<int>>(m1 + m2);
// or using an explicitly typed initializer (C++11 and later)
Matrix<int> sum2 = m1 + m2;
